ensure_install(){
  if ! syslib_ok; then
    log "INSTALL-RETRY system libs missing under /usr/lib (libssl/libcrypto/libopus)"
    say "WARN 系统库缺失, 无法启动 xz_client"
    while :; do sleep 30; log "INSTALL-RETRY waiting for /usr/lib ssl/opus"; done
  fi
  if bin_ok; then log "INSTALL OK (已在位, sha 匹配, libs=/usr/lib)"; say "二进制已在位（sha 匹配, 系统库）"; return 0; fi
  log "INSTALL-START $BIN 缺失或 sha 不符 → 解码内嵌 payload"
  say "开始安装 xz_client_armhf（sha256=$XZ_CLIENT_SHA256）"
  n=0
  while :; do
    n=$((n + 1))
    if payload_install; then return 0; fi
    log "INSTALL-RETRY 第 $n 次失败 → 30s 后重试"
    say "WARN 安装重试 第 $n 次失败（30s 后重试, 见 xiaozhi.watch.log）"
    sleep 30
  done
}

load_config(){
  [ -r "$ENVF" ] || return 0
  while IFS='=' read -r _k _v; do
    case "$_k" in
      XZ_ACCESS_TOKEN|XZ_WAKE_TEXT|XZ_LOCAL_WAKE_TEXT|XZ_TRIGGER_PHRASE|XZ_GOODBYE_TEXT|XZ_PLAYBACK|XZ_IDLE_TIMEOUT_MS|XZ_PING_INTERVAL_MS|XZ_PONG_TIMEOUT_MS|XZ_MAX_SESSION_SECONDS|XZ_FULL_DUPLEX|XZ_BARGE_IN|XZ_LOCAL_AEC|XZ_ALSA_DEVICE|XZ_CLIENT_ID_FILE|XZ_TALK_LOG|XZ_INTERRUPT_TEXT)
        case "$_k" in XZ_WS_URL|XZ_ACCESS_TOKEN)
          case "$_v" in
            \'*\') _v=${_v#\'}; _v=${_v%\'} ;;
            \"*\") _v=${_v#\"}; _v=${_v%\"} ;;
          esac ;;
        esac
        export "$_k=$_v" ;;
    esac
  done < "$ENVF"
}

script_cfg() { head -n 40 "$0" | sed -n "s/^# *${1}=//p" | head -n 1 | tr -d '\r'; }
# Read existing credentials/defaults without installation, OTA requests, log
# writes, audio access, or changing the running resident session.
publish_bind_code() {
  MAC=$(tr -d '\r\n' < /sys/class/net/wlan0/address 2>/dev/null)
  CIDF=$BASE/client_id
  mkdir -p "$BASE" 2>/dev/null
  if [ ! -s "$CIDF" ]; then
    CID=$(cat /proc/sys/kernel/random/uuid 2>/dev/null)
    case "$CID" in
      ????????-????-????-????-????????????)
        printf '%s\n' "$CID" > "$CIDF"
        chmod 600 "$CIDF" 2>/dev/null
        ;;
      *)
        log "绑定码跳过: 无法生成 Client-Id"
        say "绑定码跳过: 无法生成 Client-Id"
        return 0
        ;;
    esac
  fi
  CID=$(tr -d '\r\n' < "$CIDF")
  if [ -z "$MAC" ] || [ -z "$CID" ]; then
    log "绑定码跳过: 缺少 MAC 或 Client-Id"
    say "绑定码跳过: 缺少 MAC 或 Client-Id"
    return 0
  fi
  BODY=$(printf '{"version":2,"language":"zh-CN","mac_address":"%s","uuid":"%s","chip_model_name":"esp32s3","application":{"name":"xiaozhi","version":"1.0.0","elf_sha256":"1"},"board":{"type":"lx06","mac":"%s"}}' "$MAC" "$CID" "$MAC")
  RESP=$(curl -fsS --max-time 6 -X POST 'https://api.tenclass.net/xiaozhi/ota/' \
    -H 'Content-Type: application/json' \
    -H 'Activation-Version: 1' \
    -H "Device-Id: $MAC" \
    -H "Client-Id: $CID" \
    -H 'User-Agent: lx06/1.0.0' \
    --data "$BODY" 2>/dev/null)
  CODE=$(printf '%s' "$RESP" | sed -n 's/.*"activation"[^}]*"code"[^"]*"\([0-9][0-9][0-9][0-9][0-9][0-9]\)".*/\1/p' | head -n 1)
  if [ -n "$CODE" ]; then
    log "绑定码 $CODE  请到 https://xiaozhi.me/console/agents 填写"
    say "绑定码 $CODE  请到 https://xiaozhi.me/console/agents 填写"
  elif printf '%s' "$RESP" | grep -q '"activation"'; then
    log "绑定码解析失败"
    say "绑定码解析失败"
  elif printf '%s' "$RESP" | grep -q '"websocket"'; then
    log "小智已绑定，无需验证码"
    say "小智已绑定，无需验证码"
  else
    log "绑定码获取失败（OTA 无响应），重启脚本可再试"
    say "绑定码获取失败（OTA 无响应），重启脚本可再试"
  fi
  return 0
}
# Run the existing device-identity OTA query in a subshell. Do not restart the
# resident or access audio, and never expose the full OTA/token response.
# Check the device binding without starting audio.
binding_cache_key() {
  [ -n "${BASE:-}" ] && [ -s "$BASE/client_id" ] &&
    [ -r /sys/class/net/wlan0/address ] || return 1
  cat "$BASE/client_id" /sys/class/net/wlan0/address | sha256sum | cut -d' ' -f1
}

binding_web_load() (
  key=$(binding_cache_key) || key=
  if [ -n "$key" ] && [ "$(cat /tmp/lx06-xz-bound 2>/dev/null)" = "$key" ]; then
    config=$("$SETTINGS" show "$0") || { printf '%s\n' "$config"; exit 1; }
    values=$(printf '%s' "$config" | /usr/bin/lx06-model-tool get values) || exit 1
    printf '{"step":"configure","values":%s}\n' "$values"
  else
    binding_web_event
  fi
)

binding_web_event() (
  config=$("$SETTINGS" show "$0") || { printf '%s\n' "$config"; exit 1; }
  config_values=$(printf '%s' "$config" | /usr/bin/lx06-model-tool get values) || exit 1
  binding_result=1
  key=$(binding_cache_key) || key=
  log() { :; }
  say() {
    case "$*" in
      '绑定码 '*)
        message=$*; code=${message#绑定码 }; code=${code%% *}
        case "$code" in
          [0-9][0-9][0-9][0-9][0-9][0-9])
            [ -z "$key" ] || rm -f /tmp/lx06-xz-bound
            printf '{"step":"pair","message":"请在小智控制台添加设备并填写配对码，绑定后自动继续。","linkLabel":"打开小智控制台","link":"https://xiaozhi.me/console/agents","code":"%s","values":%s}\n' "$code" "$config_values"; binding_result=0; return;;
        esac;;
      '小智已绑定，无需验证码')
        if [ -n "$key" ]; then
          temp=$(umask 077; mktemp /tmp/lx06-xz-bound.XXXXXX) &&
            { printf '%s\n' "$key" > "$temp" && mv -f "$temp" /tmp/lx06-xz-bound || rm -f "$temp"; }
        fi
        printf '{"step":"configure","message":"小智已绑定。","values":%s}\n' "$config_values"; binding_result=0; return;;
    esac
    printf '%s\n' '{"message":"暂未获取到绑定码，请稍后再试。"}'
  }
  publish_bind_code
  exit "$binding_result"
)

# Show deployed scripts declaring the local home MCP interface.
home_mcp_options() {
  printf '%s' '{"options":{"XZ_HOME_MCP_SCRIPT":[{"value":"none","label":"请选择已上传的脚本"}'
  _home_count=0
  for _home_path in /data/lx06/apps/*.sh; do
    [ -f "$_home_path" ] && [ ! -L "$_home_path" ] || continue
    _home_name=${_home_path##*/}
    case "$_home_name" in *[!A-Za-z0-9._-]*) continue;; esac
    [ "${#_home_name}" -le 80 ] || continue
    head -c 1024 "$_home_path" | grep -Fxq '# LX06-HOME-MCP: 1' || continue
    printf ',{"value":"%s","label":"%s"}' "$_home_name" "$_home_name"
    _home_count=$((_home_count + 1))
    [ "$_home_count" -lt 63 ] || break
  done
  printf '%s\n' ']}}'
}

if [ "${1:-}" = --web-action ]; then
  load_config
  _bye=$(script_cfg "结束对话"); _bar=$(script_cfg "打断词")
  [ -z "$_bye" ] || export XZ_GOODBYE_TEXT="$_bye"
  [ -z "$_bar" ] || export XZ_INTERRUPT_TEXT="$_bar"
  case "${2:-}" in
    bind) binding_web_event; exit $?;;
    load) home_mcp_options; binding_web_load; exit $?;;
    save) exec "$SETTINGS" save "$0";;
    *) exit 2;;
  esac
fi

session_worker() {
  [ -x "$XA/processed-mic-read" ] && [ -x "$BIN" ] || return 2
  SESSION_DIR=/tmp/lx06-xz-session.$$
  (umask 077; mkdir "$SESSION_DIR") || return 2
  FIFO=$SESSION_DIR/mic
  LT=; LC=
  worker_cleanup() {
    trap - EXIT
    [ -n "$LC" ] && kill -TERM "$LC" 2>/dev/null
    [ -n "$LT" ] && kill -TERM "$LT" 2>/dev/null
    rm -f "$FIFO" "$SESSION_DIR/ready"
    rmdir "$SESSION_DIR" 2>/dev/null
    # session-run reaps all descendants, including stuck players/readers.
    :
  }
  trap worker_cleanup EXIT
  trap 'exit 143' TERM INT
  mkfifo "$FIFO" || return 2
  # Keep the stock post-AEC microphone path and additionally subtract the
  # decoded playback reference before cloud/control ASR. Native realtime VAD
  # can stop TTS before a text-level echo filter gets a chance to reject it.
  export XZ_FULL_DUPLEX=0 XZ_BARGE_IN=0 XZ_LOCAL_AEC=1 XZ_WS_URL='wss://api.tenclass.net/xiaozhi/v1/'
  # Use the stock speech mixer; default routes through the music DTS effect.
  export XZ_ALSA_DEVICE="${XZ_ALSA_DEVICE:-notify}"
  export XZ_WAKE_TEXT="${1:-${XZ_LOCAL_WAKE_TEXT:-小智小智}}"
  export XZ_TIMELINE_FILE=/tmp/lx06-xz-timeline.log XZ_MIC_FIFO="$FIFO"
  export XZ_CLIENT_ID_FILE="${XZ_CLIENT_ID_FILE:-$BASE/client_id}"
  export LD_LIBRARY_PATH=/usr/lib
  # FIFO open rendezvous occurs when the client receives its cloud hello.
  # Do not wait for reader-ready before launching the consumer.
  GLIBC_TUNABLES=glibc.pthread.rseq=0 "$XA/processed-mic-read" --name "xz-dialog" --ready-file "$SESSION_DIR/ready" > "$FIFO" 2>>"$LOG" &
  LT=$!
  XZ_HOME="$BASE" XZ_TALK_LOG="${XZ_TALK_LOG:-/data/lx06/logs/xiaozhi.talk.log}" "$SETTINGS" run "$0" /bin/sh "$0" --launch-client </dev/null >>"$LOG" 2>&1 &
  LC=$!
  log "session worker=$$ client=$LC reader=$LT wake=$XZ_WAKE_TEXT"
  while kill -0 "$LC" 2>/dev/null; do
    if ! kill -0 "$LT" 2>/dev/null; then
      # A normal client shutdown closes its FIFO before the process exits.
      # Allow that bounded tail to finish before diagnosing reader failure.
      sleep 0.2
      if kill -0 "$LC" 2>/dev/null; then
        log 'session microphone reader exited; closing cloud/player'
        return 13
      fi
      break
    fi
    sleep 0.2
  done
  wait "$LC"; result=$?
  LC=
  log "session client exit=$result"
  return "$result"
}
local_session() {
  ticket=${2:-}
  epoch=; expires=
  case "$ticket" in
    *:*) epoch=${ticket%%:*}; expires=${ticket#*:};;
    '') ;;
    *) return 2;;
  esac
  [ -z "$ticket" ] || { [ -n "$epoch" ] && [ -n "$expires" ]; } || return 2
  "$SETTINGS" run "$0" sh -c '
    limit=${XZ_MAX_SESSION_SECONDS:-900}
    keepalive=${XZ_KEEPALIVE_MINUTES:-0}
    case "$limit" in ""|*[!0-9]*|0*|??????*) limit=900;; esac
    case "$keepalive" in 0|[1-9]|[1-9][0-9]|1[01][0-9]|120) ;; *) keepalive=0;; esac
    keepalive=$((keepalive * 60))
    [ "$limit" -ge "$keepalive" ] || limit=$keepalive
    [ "$limit" -le 86400 ] || limit=86400
    export LX06_DIALOG_LIGHTS=1 LX06_SESSION_MAX_SECONDS="$limit"
    if [ -n "$4" ]; then
      exec "$1/session-run" run-local xz_watch.sh "$4" "$5" sh "$2" --session-worker "$3"
    fi
    exec "$1/session-run" run xz_watch.sh sh "$2" --session-worker "$3"
  ' lx06 "$XA" "$0" "${1:-${XZ_LOCAL_WAKE_TEXT:-小智小智}}" "$epoch" "$expires" >>"$LOG" 2>&1 &
  SPID=$!
  wait "$SPID"; result=$?
  SPID=
  log "session closed result=$result"
  # A rejected configuration or cloud failure ends this conversation only.
  # Returning nonzero from a cold --wakeup keeper job would quarantine peers.
  return 0
}
stop_resident() {
  trap - EXIT
  if [ -n "$SPID" ]; then kill -TERM "$SPID" 2>/dev/null; wait "$SPID"; fi
  rm -f "$WWEV"
  :
}

# Use the device's official token when a manual token was never configured.
xz_ota_token() (
  mac=$(tr -d '\r\n' </sys/class/net/wlan0/address) || exit 1
  cid=$(tr -d '\r\n' <"$XZ_CLIENT_ID_FILE") || exit 1
  printf '%s\n' "$mac" | grep -Eq '^([0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}$' || exit 1
  case "$cid" in ''|*[!A-Za-z0-9_-]*) exit 1;; esac
  [ "${#cid}" -le 128 ] || exit 1
  body=$(printf '{"version":2,"language":"zh-CN","mac_address":"%s","uuid":"%s","chip_model_name":"esp32s3","application":{"name":"xiaozhi","version":"1.0.0","elf_sha256":"1"},"board":{"type":"lx06","mac":"%s"}}' "$mac" "$cid" "$mac")
  response=$(curl -fsS --proto '=https' --connect-timeout 3 --max-time 6 --max-filesize 16384 \
    -H 'Content-Type: application/json' -H 'Activation-Version: 1' \
    -H "Device-Id: $mac" -H "Client-Id: $cid" -H 'User-Agent: lx06/1.0.0' \
    --data "$body" 'https://api.tenclass.net/xiaozhi/ota/' 2>/dev/null) || exit 1
  [ -z "$(printf '%s' "$response" | jsonfilter -e '@.activation' 2>/dev/null)" ] || exit 1
  url=$(printf '%s' "$response" | jsonfilter -e '@.websocket.url' 2>/dev/null) || exit 1
  [ "$url" = 'wss://api.tenclass.net/xiaozhi/v1/' ] || exit 1
  token=$(printf '%s' "$response" | jsonfilter -e '@.websocket.token' 2>/dev/null) || exit 1
  case "$token" in ''|*[!A-Za-z0-9._~+/=-]*) exit 1;; esac
  [ "${#token}" -le 512 ] || exit 1
  printf %s "$token"
)

if [ "${1:-}" = --launch-client ]; then
  [ "$#" -eq 1 ] && [ -n "${XZ_CLIENT_ID_FILE:-}" ] && [ -n "${XZ_MIC_FIFO:-}" ] || exit 2
  case "${XZ_ACCESS_TOKEN:-}" in
    ''|REPLACE_WITH_*)
      XZ_ACCESS_TOKEN=$(xz_ota_token) || { log '小智连接令牌获取失败，请检查绑定或网络'; exit 5; }
      export XZ_ACCESS_TOKEN
      ;;
  esac
  export XZ_MCP_TASK_AUTO="${XZ_MCP_TASK_AUTO:-1}"
  export XZ_LISTEN_END_WORD="${XZ_LISTEN_END_WORD-发送}"
  exec "$BIN"
fi

[ -x "$XA/session-run" ] && [ -x "$XA/processed-mic-read" ] || { say '固件缺少会话管理或麦克风订阅组件'; exit 2; }
if [ "${1:-}" != --session-worker ]; then ensure_install; drop_dup_libs; fi
# ---------------- 用户配置/默认（重部署保留） ----------------
load_config
if [ ! -f "$ENVF" ]; then
  cat > "$ENVF" <<'XZENV'
# KEY=VALUE only; this file is parsed as data, never sourced as shell.
XZ_WS_URL='wss://api.tenclass.net/xiaozhi/v1/'
XZ_ACCESS_TOKEN='REPLACE_WITH_XIAOZHI_TOKEN'
XZ_WAKE_TEXT=小爱同学召唤小智
XZ_LOCAL_WAKE_TEXT=小智小智
XZ_TRIGGER_PHRASE=召唤小智
XZ_GOODBYE_TEXT=小智再见
XZ_PLAYBACK=1
XZ_IDLE_TIMEOUT_MS=120000
XZ_MAX_SESSION_SECONDS=900
XZ_FULL_DUPLEX=0
XZ_BARGE_IN=0
XZ_LOCAL_AEC=1
XZENV
  chmod 600 "$ENVF" 2>/dev/null
  log "ENVF created (默认配置)"
