fi
[ -f "$TRIGCONF" ] || printf '召唤小智\n呼叫小智\n' > "$TRIGCONF"
chmod 666 "$TRIGCONF" 2>/dev/null
apply_script_cfg() {
  _open=$(script_cfg "开启对话")
  _bye=$(script_cfg "结束对话")
  _bar=$(script_cfg "打断词")
  if [ -n "$_open" ]; then
    printf '%s\n' "$_open" | sed 's/，/,/g;s/、/,/g' | tr ',' '\n' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//' | grep -v '^$' > "$TRIGCONF"
    export XZ_OPEN_TEXT="$_open"
    log "script-cfg open=$_open"
  fi
  if [ -n "$_bye" ]; then
    export XZ_GOODBYE_TEXT="$_bye"
    log "script-cfg goodbye=$_bye"
  fi
  if [ -n "$_bar" ]; then
    export XZ_INTERRUPT_TEXT="$_bar"
    log "script-cfg interrupt=$_bar"
  fi
}
apply_script_cfg




case "${1:-}" in
  --session-worker) session_worker "${2:-}"; exit $? ;;
  --wakeup) [ "$#" -le 3 ] || exit 2; local_session "${2:-}" "${3:-}"; exit $?;;
  '') ;;
  *) say '不支持的参数'; exit 2 ;;
esac
exec 8>/tmp/lx06-xz-resident.lock
flock -n 8 || exit 0
trap stop_resident EXIT
trap 'exit 0' TERM INT
rm -f "$WWEV"
say '常驻就绪（本地唤醒、官方优先接管）'
publish_bind_code
while :; do
  if [ -s "$WWEV" ]; then
    IFS=' ' read -r word score stamp ticket extra < "$WWEV" || :
    rm -f "$WWEV"
    # Consume only fresh directed events; never replay an event after restart.
    read -r uptime rest < /proc/uptime
    case "$stamp" in ''|*[!0-9.]*) stamp=0;; esac
    if [ -n "$word" ] && [ "${uptime%%.*}" -ge "${stamp%%.*}" ] && [ "$(( ${uptime%%.*} - ${stamp%%.*} ))" -le 3 ]; then
      [ -n "$extra" ] || local_session "$word" "$ticket"
    else
      log 'discard stale local event'
    fi
  fi
  sleep 0.1
done
